CREATE TABLE public.disciplinary_reports (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id) on delete cascade, title text not null, filters jsonb not null default '{}'::jsonb, snapshot jsonb not null default '{}'::jsonb, prepared_for_hearing boolean not null default false, created_by uuid not null, created_at timestamptz not null default now());
GRANT SELECT, INSERT, UPDATE ON public.disciplinary_reports TO authenticated;
GRANT ALL ON public.disciplinary_reports TO service_role;
ALTER TABLE public.disciplinary_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "management reads disciplinary archive" ON public.disciplinary_reports FOR SELECT TO authenticated USING (public.is_school_admin(school_id));
CREATE POLICY "management creates disciplinary archive" ON public.disciplinary_reports FOR INSERT TO authenticated WITH CHECK (public.is_school_admin(school_id) AND created_by = auth.uid());
CREATE POLICY "management updates disciplinary archive" ON public.disciplinary_reports FOR UPDATE TO authenticated USING (public.is_school_admin(school_id)) WITH CHECK (public.is_school_admin(school_id));
CREATE INDEX disciplinary_reports_school_created_idx ON public.disciplinary_reports (school_id, created_at DESC);
CREATE INDEX behaviour_notes_school_date_idx ON public.behaviour_notes (school_id, created_at DESC);
CREATE OR REPLACE FUNCTION public.can_manage_register(_school uuid, _class uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_school_admin(_school) OR EXISTS (SELECT 1 FROM public.classes c WHERE c.id = _class AND c.school_id = _school AND c.class_teacher_id = auth.uid() AND public.has_role(auth.uid(), _school, 'teacher')) $$;
CREATE OR REPLACE FUNCTION public.validate_attendance_register() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_class uuid; BEGIN SELECT s.class_id INTO v_class FROM public.students s WHERE s.id=NEW.student_id AND s.school_id=NEW.school_id AND s.deleted_at IS NULL; IF v_class IS NULL OR NEW.class_id IS DISTINCT FROM v_class THEN RAISE EXCEPTION 'Student and register class do not match'; END IF; IF NOT public.can_manage_register(NEW.school_id, NEW.class_id) AND auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Only the assigned class teacher may update this register'; END IF; NEW.updated_at := now(); RETURN NEW; END $$;
CREATE TRIGGER enforce_attendance_register BEFORE INSERT OR UPDATE ON public.attendance_records FOR EACH ROW EXECUTE FUNCTION public.validate_attendance_register();
CREATE OR REPLACE FUNCTION public.audit_admin_attendance_override() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND public.is_school_admin(NEW.school_id) AND NEW.marked_by = auth.uid() THEN IF nullif(trim(coalesce(NEW.note,'')),'') IS NULL THEN RAISE EXCEPTION 'Principal overrides require a reason'; END IF; INSERT INTO public.audit_logs (actor_id, actor_email, school_id, action, details) VALUES (auth.uid(), auth.jwt()->>'email', NEW.school_id, 'attendance_override', jsonb_build_object('student_id',NEW.student_id,'date',NEW.date,'previous_status',CASE WHEN TG_OP='UPDATE' THEN OLD.status::text ELSE NULL END,'status',NEW.status,'reason',NEW.note)); END IF; RETURN NEW; END $$;
CREATE TRIGGER audit_attendance_override BEFORE INSERT OR UPDATE ON public.attendance_records FOR EACH ROW EXECUTE FUNCTION public.audit_admin_attendance_override();
CREATE OR REPLACE FUNCTION public.can_manage_attendance_row(_school uuid, _class uuid, _student uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_manage_register(_school,_class) AND EXISTS (SELECT 1 FROM public.students s WHERE s.id=_student AND s.school_id=_school AND s.class_id=_class) $$;
CREATE POLICY "register owner inserts attendance" ON public.attendance_records FOR INSERT TO authenticated WITH CHECK (public.can_manage_attendance_row(school_id,class_id,student_id));
CREATE POLICY "register owner updates attendance" ON public.attendance_records FOR UPDATE TO authenticated USING (public.can_manage_attendance_row(school_id,class_id,student_id)) WITH CHECK (public.can_manage_attendance_row(school_id,class_id,student_id));
CREATE POLICY "register owner deletes attendance" ON public.attendance_records FOR DELETE TO authenticated USING (public.can_manage_attendance_row(school_id,class_id,student_id));
DROP POLICY IF EXISTS "staff write attendance" ON public.attendance_records;
DROP POLICY IF EXISTS "staff update attendance" ON public.attendance_records;
DROP POLICY IF EXISTS "staff delete attendance" ON public.attendance_records;
CREATE OR REPLACE FUNCTION public.prevent_behaviour_deletion() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Behaviour notes are permanent and cannot be deleted'; END $$;
CREATE TRIGGER protect_behaviour_history BEFORE DELETE ON public.behaviour_notes FOR EACH ROW EXECUTE FUNCTION public.prevent_behaviour_deletion();